<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Plus, ArrowLeft, Download, Wallet, FileText, RefreshCw } from '@lucide/vue'
import ProjectNotesTasks from '../components/ProjectNotesTasks.vue'
import MaterialTrackingPanel from '../components/MaterialTrackingPanel.vue'
import { ACTION_TYPES, ACTION_STATUSES, actionFinancials, billingStatus, canManageFunds, cents, financialSummary, procurementStatus } from '../domain/managedFunds.mjs'
import type { FundsAction, FundsActionType, FundsCommand, FundsInvoice } from '../domain/managedFunds.mjs'
import { downloadFundsDocument, loadFundsWorkspace, runFundsCommand, saveFundsProject, uploadFundsDocument } from '../services/managedFundsApi'
import type { FundsError, FundsWorkspace } from '../services/managedFundsApi'
import { currency, generateVendorPurchaseOrders } from '../services/calculations'
import { loadUsers } from '../services/auth'
import { loadVendorDirectory } from '../services/vendorDirectory'
import { exportCustomerQuotePdf, exportPurchaseOrderPdf, exportManagedFundsInvoicePdf } from '../services/pdfExports'
import { buildManagedFundsFinancialReport } from '../services/managedFundsFinancialReport.mjs'
import { exportManagedFundsCustomerFinancialWorkbook } from '../services/customerFinancialExports'
import { exportManagedFundsWorkbook, exportProjectTrackingWorkbook } from '../services/workbookExports'
import { parseTrackingImportFile } from '../services/trackingImport'
import { importMaterialTracking, mergeMaterialTrackingScope } from '../services/materialTracking'
import type { Project, CustomerQuote } from '../types'

const route = useRoute(), router = useRouter()
const workspace = ref<FundsWorkspace>(), busy = ref(false), error = ref(''), notice = ref(''), fundingError = ref<Record<string, number>>()
const newNote=ref(''), invoiceFilter=ref('all')
const section = ref(route.query.tab === 'notes-tasks' ? 'notes-tasks' : 'ledger'), actionTab = ref('Overview'), chooser = ref(false), newType = ref<FundsActionType>(), operation = ref(''), invoiceComposer = ref(false)
const pendingCommand = ref<FundsCommand>()
const fileInput = ref<HTMLInputElement>(), trackingInput = ref<HTMLInputElement>(), documentKind = ref('Supporting document')
const filters = reactive({ search: '', type: '', status: '', vendor: '', owner: '', from: '', to: '', invoiced: '', open: '', report: '' })
const form = reactive<Record<string, any>>({})
const draft = reactive({ invoiceDate: today(), dueDate: today(), amounts: {} as Record<string, number> })
const state = computed(() => workspace.value?.state), project = computed(() => workspace.value?.project)
const action = computed(() => state.value?.actions.find(a => a.id === String(route.params.actionId || '')))
const totals = computed(() => financialSummary(state.value))
const actionTotals = computed(() => action.value && state.value ? actionFinancials(state.value, action.value.id) : undefined)
const permitted = (p: string) => canManageFunds(workspace.value?.actor, p)
const money = (value = 0) => currency(value / 100)
const users = computed(() => loadUsers().filter(u => u.active))
const vendors = computed(() => [...new Set([...loadVendorDirectory().map(v => v.vendor), ...(state.value?.actions.flatMap(a => a.vendors) || [])])].sort())
const materialAction = computed(() => ['Purchase Material', 'Direct Expense / Pass-Through'].includes(action.value?.type || ''))
const actionTabs = computed(() => ['Overview', ...(materialAction.value && (action.value?.type === 'Purchase Material' || action.value?.quoteIds.length || action.value?.poIds.length) ? ['Procurement', 'Tracking'] : []), ...(materialAction.value ? ['Expenses'] : []), ...(!['Funding Modification', 'Credit / Adjustment'].includes(action.value?.type || '') ? ['Billing'] : []), 'Documents', 'Notes & Activity'])
const scopedQuotes = computed(() => project.value?.quotes.filter(q => !action.value || q.actionId === action.value.id || action.value.quoteIds.includes(q.id)) || [])
const scopedPOs = computed(() => project.value?.purchaseOrders.filter(p => !action.value || p.actionId === action.value.id || action.value.poIds.includes(p.id)) || [])
const scopedProject = computed(() => project.value ? { ...project.value, quotes: scopedQuotes.value, purchaseOrders: scopedPOs.value, materialShipments: project.value.materialShipments?.filter(s => scopedPOs.value.some(p => p.id === s.poId)) } : undefined)
const invoices = computed(() => state.value?.invoices.filter(i => (!action.value || i.allocations.some(a => a.actionId === action.value!.id)) && (invoiceFilter.value==='all' || invoiceFilter.value==='unpaid' && i.status==='Issued' && unpaid(i)>0 || invoiceFilter.value==='paid' && i.status==='Issued' && unpaid(i)===0 || i.status===invoiceFilter.value)) || [])
const transactions = computed(() => state.value?.transactions.filter(t => !action.value || t.actionId === action.value.id || t.adjustmentActionId === action.value.id) || [])
const documents = computed(() => state.value?.documents.filter(d => !action.value || d.actionId === action.value.id) || [])
const activity = computed(() => state.value?.audit.filter(a => !action.value || a.targetId === action.value.id || action.value.quoteIds.includes(a.targetId) || action.value.poIds.includes(a.targetId) || transactions.value.some(t => t.id === a.targetId)) || [])
const review = computed(() => state.value?.review.filter(r => !r.resolved) || [])
const billableActions = computed(() => state.value?.actions.filter(a => a.readyToBill && a.status !== 'Cancelled' && actionFinancials(state.value!, a.id).billable > 0) || [])
const rows = computed(() => (state.value?.actions || []).map(a => ({ action: a, financial: actionFinancials(state.value!, a.id), procurement: procurementStatus(project.value!, a), billing: billingStatus(state.value!, a) })).filter(row => {
  const a = row.action, t = row.financial
  const quotes = project.value?.quotes.filter(q => q.actionId === a.id || a.quoteIds.includes(q.id)) || []
  const pos = project.value?.purchaseOrders.filter(p => p.actionId === a.id || a.poIds.includes(p.id)) || []
  const inv = state.value!.invoices.filter(i => i.allocations.some(x => x.actionId === a.id))
  const haystack = [a.number, a.description, ...a.vendors, ...quotes.flatMap(q => [q.quoteNumber, ...q.lines.flatMap(l => [l.partNumber, l.quoteNumber, l.vendor])]), ...pos.flatMap(p => [p.poNumber, p.vendor, ...p.lines.map(l => l.partNumber)]), ...inv.map(i => i.number), ...state.value!.transactions.filter(t=>t.actionId===a.id || t.adjustmentActionId===a.id).map(t=>t.reference || '')].join(' ').toLowerCase()
  return (!filters.search || haystack.includes(filters.search.toLowerCase())) && (!filters.type || a.type === filters.type) && (!filters.status || a.status === filters.status) && (!filters.vendor || a.vendors.includes(filters.vendor) || pos.some(p => p.vendor === filters.vendor)) && (!filters.owner || a.ownerId === filters.owner) && (!filters.from || a.requestDate >= filters.from) && (!filters.to || a.requestDate <= filters.to) && (!filters.invoiced || (filters.invoiced === 'yes' ? t.invoiced > 0 : t.invoiced === 0)) && (!filters.open || (filters.open === 'open' ? !['Complete', 'Cancelled'].includes(a.status) : ['Complete', 'Cancelled'].includes(a.status))) && (!filters.report || (filters.report === 'undelivered' ? a.type === 'Purchase Material' && row.procurement !== 'Delivered' && a.status !== 'Cancelled' : filters.report === 'completed-unbilled' ? a.status === 'Complete' && t.billAmount > t.invoiced : a.type === 'Direct Expense / Pass-Through' && t.actualCost > 0 && t.billAmount > t.invoiced))
}))
const counts = computed(() => ({ pending: state.value?.actions.filter(a => ['Draft', 'Pending Approval'].includes(a.status)).length || 0, pos: project.value?.purchaseOrders.filter(p => !['Delivered', 'Received', 'Cancelled'].includes(p.status)).length || 0, transit: state.value?.actions.filter(a => procurementStatus(project.value!, a) === 'In Transit').length || 0, expenses: state.value?.actions.filter(a => a.type === 'Direct Expense / Pass-Through' && actionFinancials(state.value!, a.id).actualCost > 0 && actionFinancials(state.value!, a.id).billable > 0).length || 0, drafts: state.value?.invoices.filter(i => i.status === 'Draft').length || 0 }))

function today() { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}` }
function showError(e: unknown) { error.value = e instanceof Error ? e.message : 'Operation failed.'; fundingError.value = (e as FundsError)?.funding }
async function refresh() { if (busy.value) return; busy.value = true; error.value = ''; try { workspace.value = await loadFundsWorkspace(String(route.params.id)) } catch (e) { showError(e) } finally { busy.value = false } }
onMounted(refresh)
watch(() => route.params.id, refresh)
watch(() => route.params.actionId, () => { actionTab.value = 'Overview'; error.value = ''; notice.value = ''; operation.value = ''; newType.value = undefined; invoiceComposer.value = false })
function resetForm(values: Record<string, any>) { Object.keys(form).forEach(k => delete form[k]); Object.assign(form, values); pendingCommand.value = undefined }
function selectType(type: FundsActionType) {
  chooser.value = false
  if (type === 'Create Customer Invoice') { openInvoice(); return }
  openNew(type)
}
function openNew(type: FundsActionType) { invoiceComposer.value = false; newType.value = type; resetForm({ description: '', requestDate: today(), requestor: project.value?.customerContactName || project.value?.customer, ownerId: workspace.value?.actor.id, authorizedAmount: 0, estimatedCost: 0, billAmount: 0, vendor: '', notes: '' }) }
async function execute(type: string, input: Record<string, any>, actionId = action.value?.id) {
  if (!state.value || !project.value || busy.value) return false
  busy.value = true; error.value = ''; fundingError.value = undefined; notice.value = ''
  if (['create','draft_invoice','issue_invoice','void_draft','payment','review'].includes(type)) actionId = undefined
  const signature = JSON.stringify({ type, actionId, input })
  if (!pendingCommand.value || JSON.stringify({ type: pendingCommand.value.type, actionId: pendingCommand.value.actionId, input: pendingCommand.value.input }) !== signature) pendingCommand.value = { id: crypto.randomUUID(), type, actionId, input }
  try {
    workspace.value = await runFundsCommand(project.value.id, state.value.revision, pendingCommand.value)
    pendingCommand.value = undefined; notice.value = 'Saved to the Managed Funds ledger.'; return true
  } catch (e) { showError(e); return false } finally { busy.value = false }
}
async function createAction() {
  try {
    const owner = users.value.find(u => u.id === form.ownerId)
    if (await execute('create', { ...form, type: newType.value, vendors: form.vendor ? [form.vendor] : [], ownerName: owner?.name || workspace.value?.actor.name, authorizedAmount: cents(form.authorizedAmount), estimatedCost: cents(form.estimatedCost), billAmount: cents(form.billAmount) }, undefined)) {
      newType.value = undefined; const created = state.value!.actions.at(-1)!; await router.push(`/projects/${project.value!.id}/actions/${created.id}`)
    }
  } catch (e) { showError(e) }
}
function openOperation(type: string) {
  operation.value = type
  resetForm({ ...(action.value || {}), authorizedAmount: (action.value?.authorizedAmount || 0) / 100, estimatedCost: (action.value?.estimatedCost || 0) / 100, billAmount: (actionTotals.value?.billAmount || 0) / 100, commitment: (actionTotals.value?.billAmount || 0) / 100, actualCost: 0, amount: 0, reason: '', overrideReason: '', reference: '', vendor: action.value?.vendors[0] || '', vendorInvoiceNumber: '', expenseDate: today(), description: action.value?.description || '', kind: 'Customer Credit', targetActionId: '', invoiceId: '', documentId: '' })
}
async function submitOperation() {
  try {
    const input = { ...form }
    if (operation.value === 'edit') {
      for (const k of ['authorizedAmount', 'estimatedCost', 'billAmount']) input[k] = cents(form[k])
      const owner = users.value.find(u => u.id === form.ownerId); if (owner) input.ownerName = owner.name
      input.vendors = form.vendor ? [form.vendor] : action.value?.vendors || []
    }
    if (operation.value === 'approve') input.commitment = cents(form.commitment)
    if (operation.value === 'expense') { input.actualCost = cents(form.actualCost); input.billAmount = cents(form.billAmount) }
    if (['funding', 'adjust', 'payment'].includes(operation.value)) input.amount = cents(form.amount)
    if (await execute(operation.value, input)) operation.value = ''
  } catch (e) { showError(e) }
}
function openInvoice() { invoiceComposer.value = true; chooser.value = false; pendingCommand.value = undefined; for (const key of Object.keys(draft.amounts)) delete draft.amounts[key]; if (action.value && state.value && action.value.readyToBill) draft.amounts[action.value.id] = Math.max(0, actionFinancials(state.value, action.value.id).billable) / 100 }
async function draftInvoice() {
  try { if (await execute('draft_invoice', { invoiceDate: draft.invoiceDate, dueDate: draft.dueDate, projectNumber: project.value?.projectNumber, allocations: Object.entries(draft.amounts).filter(([, n]) => n > 0).map(([actionId, n]) => ({ actionId, amount: cents(n) })) }, undefined)) { invoiceComposer.value = false; section.value = 'billing'; actionTab.value = 'Billing' } } catch (e) { showError(e) }
}
function unpaid(i: FundsInvoice) { return state.value?.transactions.filter(t => t.invoiceId === i.id).reduce((n, t) => n + t.invoiced - t.paid, 0) || 0 }
function payment(i: FundsInvoice) { openOperation('payment'); form.invoiceId = i.id; form.amount = unpaid(i) / 100 }
function voidDraft(i: FundsInvoice) { openOperation('void_draft'); form.invoiceId = i.id }
async function saveProject(next: Project, approvalQuoteId?: string) {
  if (busy.value) return; busy.value = true; error.value = ''; try { workspace.value = await saveFundsProject(next, approvalQuoteId); notice.value = 'Project documents saved.' } catch (e) { showError(e) } finally { busy.value = false }
}
async function approveQuote(q: CustomerQuote) { if (!project.value) return; await saveProject({ ...project.value, quotes: project.value.quotes.map(item => item.id === q.id ? { ...item, status: 'Customer Approved', lines: item.lines.map(l => ({ ...l, approved: true })) } : item) }, q.id) }
async function issuePos(q: CustomerQuote) {
  if (!project.value || scopedPOs.value.some(p => p.quoteId === q.id)) return
  const max = project.value.purchaseOrders.reduce((n, p) => Math.max(n, Number(p.poNumber.match(/-(\d{4})-/)?.[1] || 0)), 0)
  const pos = generateVendorPurchaseOrders(q.lines, project.value.projectNumber, max).map(po => ({ ...po, quoteId: q.id, actionId: q.actionId, actionNumber: q.actionNumber }))
  await saveProject({ ...project.value, purchaseOrders: [...project.value.purchaseOrders, ...pos] })
}
async function saveProjectWork(next: Project) {
  if (busy.value) throw new Error('Wait for the current save to finish.')
  busy.value = true
  try { workspace.value = await saveFundsProject(next) } finally { busy.value = false }
}
async function saveTracking(next: Project) {
  if (!project.value) return
  await saveProjectWork(mergeMaterialTrackingScope(project.value, next))
}
async function importTracking(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0]; if (!file || !scopedProject.value) return
  try { const result = importMaterialTracking(scopedProject.value, await parseTrackingImportFile(file), { ...workspace.value!.actor, name: workspace.value!.actor.name || 'Atlas', role: 'Procurement Team' }); await saveTracking(result.project); if (result.review.length) notice.value = `${result.review.length} tracking rows require review; unmatched source rows were not applied.` } catch (e) { showError(e) }
  ;(event.target as HTMLInputElement).value = ''
}
async function upload(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0]; if (!file || !action.value || !state.value || busy.value) return
  busy.value = true; error.value = ''; try { workspace.value = await uploadFundsDocument(project.value!.id, action.value.id, state.value.revision, file, documentKind.value); notice.value = 'Supporting document uploaded.' } catch (e) { showError(e) } finally { busy.value = false; (event.target as HTMLInputElement).value = '' }
}
async function download(documentId: string) { try { await downloadFundsDocument(project.value!.id, documentId) } catch (e) { showError(e) } }
async function exportLedger() { if (project.value && state.value) await exportManagedFundsWorkbook(project.value, state.value, rows.value.map(r => r.action.id)) }
async function exportCustomerSummary() {
  if (!project.value || busy.value) return
  busy.value = true; error.value = ''; notice.value = ''
  try {
    workspace.value = await loadFundsWorkspace(project.value.id)
    await exportManagedFundsCustomerFinancialWorkbook(buildManagedFundsFinancialReport(workspace.value.project, workspace.value.state))
    notice.value = 'Customer Excel downloaded from the latest saved data.'
  } catch (e) { showError(e) } finally { busy.value = false }
}
function resolveReview(id: string) { openOperation('review'); form.reviewId = id }
</script>

<template>
  <main class="mf-page" :aria-busy="busy">
    <header class="mf-header">
      <div><RouterLink class="mf-back" :to="action ? `/projects/${route.params.id}` : '/projects'"><ArrowLeft :size="15"/> {{ action ? 'Managed Funds dashboard' : 'Projects' }}</RouterLink><div class="mf-eyebrow"><Wallet :size="16"/> MANAGED FUNDS <span v-if="project">{{ project.projectNumber }}</span></div><h1>{{ action ? `${action.number} · ${action.description}` : project?.projectName || 'Managed Funds' }}</h1><p>{{ project?.customer }}<span v-if="action"> · {{ action.type }} · {{ project?.projectNumber }}</span></p></div>
      <div class="mf-actions"><button class="secondary-action" :disabled="busy" @click="refresh"><RefreshCw :size="16"/> Refresh</button><RouterLink v-if="project && !action" class="secondary-action" :to="`/projects/${project.id}/edit`">Project details</RouterLink><button v-if="!action && permitted('create')" class="primary-action" :disabled="busy" @click="chooser = true"><Plus :size="17"/> New Action</button></div>
    </header>
    <div v-if="error" class="mf-alert" role="alert"><strong>{{ error }}</strong><p v-if="fundingError">Authorized Funding: {{ money(fundingError.authorizedFunding) }} · Current Commitments: {{ money(fundingError.currentCommitments) }} · Proposed Commitment: {{ money(fundingError.proposedCommitment) }} · Projected Remaining Balance: {{ money(fundingError.projectedRemainingBalance) }}</p><p v-if="error.includes('changed')">Refresh the workspace, review the latest balances, and retry your change.</p></div>
    <p v-if="notice" class="mf-notice" role="status">{{ notice }}</p>
    <p v-if="!workspace && busy" class="mf-empty">Loading funding and financial history…</p>
    <template v-if="workspace && project && state">
      <p v-if="route.params.actionId && !action" class="mf-alert">Action not found in this project.</p>
      <section v-if="!action" class="mf-cards" aria-label="Project financial summary">
        <article><span>Authorized Funding</span><strong>{{ money(totals.authorized) }}</strong><small>Original funding + modifications</small></article>
        <article><span>Committed</span><strong>{{ money(totals.committed) }}</strong><small>Approved funding reservations</small></article>
        <article><span>Actual Cost</span><strong>{{ money(totals.actualCost) }}</strong><small>Recorded vendor costs, net of credits</small></article>
        <article><span>Customer Invoiced</span><strong>{{ money(totals.invoiced) }}</strong><small>Issued invoices, net of credits</small></article>
        <article :class="{ negative: totals.available < 0 }"><span>Available Balance</span><strong>{{ money(totals.available) }}</strong><small>Authorized − committed</small></article>
        <article><span>Unbilled Balance</span><strong>{{ money(totals.unbilled) }}</strong><small>Authorized − customer invoiced</small></article>
      </section>
      <div v-if="!action" class="mf-counts"><span>{{ counts.pending }} pending actions</span><span>{{ counts.pos }} open POs</span><span>{{ counts.transit }} actions in transit</span><button @click="section='ledger'; filters.report='expenses'">{{ counts.expenses }} expenses awaiting billing</button><button @click="section='billing'">{{ counts.drafts }} draft invoices</button></div>
      <nav class="mf-tabs" aria-label="Workspace sections"><template v-if="action"><button v-for="tab in actionTabs" :key="tab" :class="{ active: actionTab === tab }" @click="actionTab=tab">{{ tab }}</button></template><template v-else><button v-for="tab in ['ledger','billing','history','documents','notes-tasks','review']" :key="tab" :class="{active:section===tab}" @click="section=tab">{{ tab === 'notes-tasks' ? 'Notes & Tasks' : tab === 'ledger' ? 'Action Ledger' : tab === 'history' ? 'Financial History' : tab === 'review' ? `Migration Review (${review.length})` : tab[0].toUpperCase()+tab.slice(1) }}</button></template></nav>

      <ProjectNotesTasks v-if="!action && section==='notes-tasks'" :key="project.id" :project="project" :persist="saveProjectWork"/>
      <section v-if="!action && section==='ledger'" class="mf-panel">
        <div class="mf-section-head"><div><h2>Managed Funds Ledger</h2><p>{{ state.actions.length }} actions · {{ rows.length }} matching filters</p></div><button class="secondary-action" :disabled="busy" @click="exportCustomerSummary"><Download :size="16"/> Customer Excel</button></div>
        <div class="mf-filters">
          <label class="mf-search">Search<input v-model="filters.search" type="search" placeholder="Action, description, vendor, PO, quote, invoice, part…"/></label>
          <label>Action Type<select v-model="filters.type"><option value="">All types</option><option v-for="t in ACTION_TYPES" :key="t">{{ t }}</option></select></label>
          <label>Status<select v-model="filters.status"><option value="">All statuses</option><option v-for="s in ACTION_STATUSES" :key="s">{{ s }}</option></select></label>
          <label>Vendor<select v-model="filters.vendor"><option value="">All vendors</option><option v-for="v in vendors" :key="v">{{ v }}</option></select></label>
          <label>Assigned Owner<select v-model="filters.owner"><option value="">All owners</option><option v-for="u in users" :key="u.id" :value="u.id">{{ u.name }}</option></select></label>
          <label>From<input v-model="filters.from" type="date"/></label><label>Through<input v-model="filters.to" type="date"/></label>
          <label>Billing<select v-model="filters.invoiced"><option value="">Any billing</option><option value="yes">Invoiced</option><option value="no">Not invoiced</option></select></label>
          <label>Open / Closed<select v-model="filters.open"><option value="">All actions</option><option value="open">Open</option><option value="closed">Closed</option></select></label>
          <label>Report<select v-model="filters.report"><option value="">All actions</option><option value="undelivered">Material not delivered</option><option value="completed-unbilled">Completed, not fully invoiced</option><option value="expenses">Expenses awaiting billing</option></select></label>
        </div>
        <div class="mf-table"><table><thead><tr><th>Action # / Date</th><th>Type / Description</th><th>Requestor / Owner</th><th>Action / Procurement / Billing</th><th>Authorized</th><th>Committed</th><th>Actual Cost</th><th>Bill Amount</th><th>Invoiced</th><th>Uninvoiced Commitment</th></tr></thead><tbody><tr v-for="r in rows" :key="r.action.id"><td><RouterLink :to="`/projects/${project.id}/actions/${r.action.id}`">{{ r.action.number }}</RouterLink><small>{{ r.action.requestDate }}</small></td><td><strong>{{ r.action.description }}</strong><small>{{ r.action.type }}</small></td><td>{{ r.action.requestor || '—' }}<small>{{ r.action.ownerName }}</small></td><td><span class="mf-pill">{{ r.action.status }}</span><small v-if="r.action.type==='Purchase Material'">{{ r.procurement }}</small><small>{{ r.billing }}</small></td><td>{{ money(r.action.type==='Funding Modification' ? r.financial.authorized : r.action.authorizedAmount) }}</td><td>{{ money(r.financial.committed) }}</td><td>{{ money(r.financial.actualCost) }}</td><td>{{ money(r.financial.billAmount) }}</td><td>{{ money(r.financial.invoiced) }}</td><td>{{ money(r.financial.variance) }}</td></tr><tr v-if="!rows.length"><td colspan="10" class="mf-empty">{{ state.actions.length ? 'No actions match these filters.' : 'Create your first Action to use the authorized funding.' }}</td></tr></tbody></table></div>
      </section>

      <section v-if="action && actionTab==='Overview'" class="mf-panel">
        <div class="mf-section-head"><div><h2>Action overview</h2><p>{{ action.requestDate }} · Requestor: {{ action.requestor || '—' }} · Owner: {{ action.ownerName }}</p></div><button v-if="permitted('edit') && !['Complete','Cancelled'].includes(action.status)" class="secondary-action" @click="openOperation('edit')">Edit Action</button></div>
        <div class="mf-statuses"><span><small>Action Status</small><b>{{ action.status }}</b></span><span v-if="action.type==='Purchase Material'"><small>Procurement Status</small><b>{{ procurementStatus(project, action) }}</b></span><span><small>Billing Status</small><b>{{ billingStatus(state, action) }}</b></span></div>
        <div v-if="actionTotals" class="mf-cards mf-action-cards"><article v-for="[label,value] in [['Authorized',action.authorizedAmount],['Estimated Cost',action.estimatedCost],['Committed',actionTotals.committed],['Actual Cost',actionTotals.actualCost],['Bill Amount',actionTotals.billAmount],['Invoiced',actionTotals.invoiced]]" :key="String(label)"><span>{{ label }}</span><strong>{{ money(Number(value)) }}</strong></article></div>
        <div class="mf-actions" v-if="!['Complete','Cancelled'].includes(action.status)">
          <button v-if="action.status==='Draft' && permitted('edit')" class="secondary-action" :disabled="busy" @click="execute('status',{status:'Pending Approval'})">Submit for approval</button>
          <button v-if="permitted('approve') && !['Funding Modification','Credit / Adjustment'].includes(action.type)" class="primary-action" @click="openOperation('approve')">Approve / Change Commitment</button>
          <button v-if="action.type==='Funding Modification' && permitted('funding')" class="primary-action" @click="openOperation('funding')">Post Funding Modification</button>
          <button v-if="action.type==='Credit / Adjustment' && permitted('adjust')" class="primary-action" @click="openOperation('adjust')">Post Credit / Adjustment</button>
          <button v-if="['Approved','In Progress'].includes(action.status) && permitted('edit')" class="secondary-action" :disabled="busy" @click="execute('status',{status:'Complete'})">Mark Complete</button>
          <button v-if="permitted('cancel')" class="secondary-action" @click="openOperation('cancel')">Cancel Action</button>
        </div>
        <p class="mf-help">{{ action.type === 'Funding Modification' ? 'Post a signed change to authorized funding. The original funding amount stays in history.' : action.type === 'Credit / Adjustment' ? 'Choose the affected Action and financial balance. Corrections post new transactions.' : 'Approval reserves customer funding. Completion retains the funding consumed by this Action.' }}</p>
        <p>{{ action.notes || 'No notes yet.' }}</p>
        <button v-if="action.type==='Direct Expense / Pass-Through' && permitted('edit')" class="mf-link" @click="actionTab='Procurement'">Optional: create a quote or purchase order</button>
      </section>

      <section v-if="action && actionTab==='Procurement'" class="mf-panel">
        <div class="mf-section-head"><div><h2>Procurement</h2><p>Use Atlas quoting to prepare a MEL, solicit multiple vendors, import their quotes, and generate customer pricing.</p></div><RouterLink v-if="permitted('edit')" class="primary-action" :to="`/projects/${project.id}/quotes/new?actionId=${action.id}`">New Quote / RFQ</RouterLink></div>
        <div v-for="q in scopedQuotes" :key="q.id" class="mf-record"><div><RouterLink :to="`/projects/${project.id}/quotes/${q.id}/edit`">{{ q.quoteNumber }} · {{ q.quoteName }}</RouterLink><small>{{ q.status }} · {{ q.lines.length }} lines · {{ action.number }}</small></div><div class="mf-actions"><button class="secondary-action" @click="exportCustomerQuotePdf(q,project)">Quote PDF</button><button v-if="q.status!=='Customer Approved' && permitted('approve')" class="secondary-action" :disabled="busy" @click="approveQuote(q)">Customer Approved</button><button v-if="q.status==='Customer Approved' && !scopedPOs.some(p=>p.quoteId===q.id) && permitted('issue_po')" class="primary-action" :disabled="busy" @click="issuePos(q)">Generate Vendor POs</button></div></div>
        <p v-if="!scopedQuotes.length" class="mf-empty">No quotes yet. Create a quote to use the existing RFQ and vendor response workflow.</p>
        <h3>Purchase orders</h3><div v-for="po in scopedPOs" :key="po.id" class="mf-record"><div><RouterLink :to="`/purchase-orders/${po.id}`">{{ po.poNumber }}</RouterLink><small>{{ po.vendor }} · {{ po.status }} · {{ currency(po.totalCost) }}</small></div><button class="secondary-action" @click="exportPurchaseOrderPdf(po,project)">PO PDF</button></div>
      </section>
      <section v-if="action && actionTab==='Tracking' && scopedProject" :class="{'mf-saving':busy}"><MaterialTrackingPanel :project="scopedProject" :persist="saveTracking" @export="exportProjectTrackingWorkbook(scopedProject)" @import="trackingInput?.click()"/><input ref="trackingInput" hidden type="file" accept=".xlsx,.csv" @change="importTracking"/></section>
      <section v-if="action && actionTab==='Expenses'" class="mf-panel"><div class="mf-section-head"><div><h2>Expenses & vendor invoices</h2><p>Record incurred costs using a vendor invoice or receipt. Customer billing is handled separately.</p></div><button v-if="['Approved','In Progress','Complete'].includes(action.status) && ['Purchase Material','Direct Expense / Pass-Through'].includes(action.type) && permitted('expense')" class="primary-action" :disabled="busy" @click="openOperation('expense')">Record Actual Cost</button></div><div v-for="tx in transactions.filter(t=>t.actualCost!==0)" :key="tx.id" class="mf-record"><div><strong>{{ tx.kind }} · {{ tx.vendor || tx.description }}</strong><small>{{ tx.reference }} · {{ tx.expenseDate || tx.occurredAt.slice(0,10) }} · {{ tx.reason }}</small></div><b>{{ money(tx.actualCost) }}</b></div><p v-if="!transactions.some(t=>t.actualCost!==0)" class="mf-empty">No incurred costs recorded.</p></section>

      <section v-if="(!action && section==='billing') || (action && actionTab==='Billing')" class="mf-panel"><div class="mf-section-head"><div><h2>Customer billing</h2><label>Invoice filter<select v-model="invoiceFilter"><option value="all">All invoices</option><option value="Draft">Draft invoices</option><option value="unpaid">Unpaid invoices</option><option value="paid">Paid / credited invoices</option><option value="Void">Voided drafts</option></select></label><p>Invoices can consolidate multiple Actions. Draft allocations reserve billing capacity.</p></div><div class="mf-actions"><button v-if="action && permitted('invoice')" class="secondary-action" :disabled="busy" @click="execute('ready',{ready:!action.readyToBill})">{{ action.readyToBill ? 'Mark Not Ready to Bill' : 'Mark Ready to Bill' }}</button><button v-if="permitted('invoice')" class="primary-action" @click="openInvoice">Create Customer Invoice</button></div></div><div v-for="i in invoices" :key="i.id" class="mf-invoice"><div class="mf-section-head"><div><h3>{{ i.number }}</h3><p>{{ i.status }} · {{ i.invoiceDate }} · Due {{ i.dueDate }} · {{ money(i.total) }}<span v-if="i.status==='Issued'"> · Unpaid {{ money(unpaid(i)) }}</span></p></div><div class="mf-actions"><button class="secondary-action" @click="exportManagedFundsInvoicePdf(project,i,state)">Invoice PDF</button><button v-if="i.status==='Draft' && permitted('invoice')" class="primary-action" :disabled="busy" @click="execute('issue_invoice',{invoiceId:i.id},undefined)">Issue Invoice</button><button v-if="i.status==='Draft' && permitted('invoice')" class="secondary-action" @click="voidDraft(i)">Void Draft</button><button v-if="i.status==='Issued' && unpaid(i)>0 && permitted('invoice')" class="secondary-action" @click="payment(i)">Record Payment</button></div></div><div v-for="allocation in i.allocations" :key="allocation.id" class="mf-allocation"><RouterLink :to="`/projects/${project.id}/actions/${allocation.actionId}`">{{ allocation.actionNumber }} · {{ allocation.description }}</RouterLink><b>{{ money(allocation.amount) }}</b></div></div><p v-if="!invoices.length" class="mf-empty">No customer invoices yet.</p></section>

      <section v-if="(!action && section==='documents') || (action && actionTab==='Documents')" class="mf-panel"><div class="mf-section-head"><div><h2>Documents</h2><p>Files remain linked to both the project and Action.</p></div><div v-if="action && permitted('edit')" class="mf-actions"><select v-model="documentKind" aria-label="Document type"><option>Supporting document</option><option>Vendor invoice / receipt</option><option>Vendor RFQ</option><option>Vendor quote</option><option>Customer approval</option></select><button class="primary-action" :disabled="busy" @click="fileInput?.click()">Upload document</button><input ref="fileInput" hidden type="file" accept=".pdf,.png,.jpg,.jpeg,.txt,.csv,.xlsx,.docx,.msg,.eml" @change="upload"/></div></div><div v-for="d in documents" :key="d.id" class="mf-record"><div><strong>{{ d.name }}</strong><small>{{ d.kind }} · {{ d.uploadedAt.slice(0,10) }} · {{ state.actions.find(a=>a.id===d.actionId)?.number }}</small></div><button class="secondary-action" @click="download(d.id)">Download</button></div><div v-for="q in scopedQuotes" :key="q.id" class="mf-record"><span>Customer quote {{ q.quoteNumber }} · {{ q.actionNumber }}</span><button class="secondary-action" @click="exportCustomerQuotePdf(q,project)">Generate PDF</button></div><div v-for="po in scopedPOs" :key="po.id" class="mf-record"><span>Purchase order {{ po.poNumber }} · {{ po.actionNumber }}</span><button class="secondary-action" @click="exportPurchaseOrderPdf(po,project)">Generate PDF</button></div></section>

      <section v-if="(!action && section==='history') || (action && actionTab==='Notes & Activity')" class="mf-panel"><div class="mf-section-head"><div><h2>Financial history & activity</h2><p>Every correction remains a separate posting. Values below are signed changes.</p></div><button class="secondary-action" @click="exportLedger">Internal ledger Excel</button></div><div class="mf-table"><table><thead><tr><th>Date / User</th><th>Type / Reference</th><th>Action</th><th>Funding</th><th>Commitment</th><th>Actual Cost</th><th>Bill Amount</th><th>Invoiced</th><th>Paid</th><th>Reason</th></tr></thead><tbody><tr v-for="t in [...transactions].reverse()" :key="t.id"><td>{{ t.occurredAt }}<small>{{ t.userName }}</small></td><td>{{ t.kind }}<small>{{ t.reference }}</small></td><td>{{ state.actions.find(a=>a.id===t.actionId)?.number || 'Project' }}</td><td>{{ money(t.authorized) }}</td><td>{{ money(t.committed) }}</td><td>{{ money(t.actualCost) }}</td><td>{{ money(t.billAmount) }}</td><td>{{ money(t.invoiced) }}</td><td>{{ money(t.paid) }}</td><td>{{ t.reason }}</td></tr></tbody></table></div><h3>Activity log</h3><details v-for="entry in [...activity].reverse()" :key="entry.id" class="mf-audit"><summary>{{ entry.occurredAt }} · {{ entry.userName }} · {{ entry.operation }}</summary><p>{{ entry.reason }}</p><div class="mf-audit-values"><div><b>Previous value</b><pre>{{ JSON.stringify(entry.previous,null,2) }}</pre></div><div><b>New value</b><pre>{{ JSON.stringify(entry.next,null,2) }}</pre></div></div></details><h3 v-if="action">Notes</h3><p v-if="action" style="white-space:pre-wrap">{{ action.notes || 'No notes recorded.' }}</p><form v-if="action && permitted('edit')" class="mf-form" @submit.prevent="execute('note',{note:newNote}).then(saved=>{if(saved)newNote=''})"><label>Add a note<textarea v-model="newNote" required/></label><button class="primary-action" :disabled="busy">Add Note</button></form></section>

      <section v-if="!action && section==='review'" class="mf-panel"><h2>Migration review</h2><p>Original project fields and source records are preserved. Reconcile uncertain historical amounts using source documents.</p><div v-for="r in state.review" :key="r.id" class="mf-record"><div><strong>{{ r.recordType }} · {{ r.resolved ? 'Resolved' : 'Review required' }}</strong><p>{{ r.reason }}</p><small>{{ r.resolution }}</small></div><button v-if="!r.resolved && permitted('adjust')" class="secondary-action" @click="resolveReview(r.id)">Record reconciliation</button></div><p v-if="!state.review.length" class="mf-empty">No migration issues require review.</p></section>
    </template>

    <div v-if="chooser || newType || operation || invoiceComposer" class="mf-overlay" @click.self="!busy && (chooser=false,newType=undefined,operation='',invoiceComposer=false)">
      <section class="mf-dialog" role="dialog" aria-modal="true" :aria-label="chooser ? 'What would you like to do?' : newType || operation || 'Create customer invoice'">
        <button class="mf-close" :disabled="busy" aria-label="Close dialog" @click="chooser=false;newType=undefined;operation='';invoiceComposer=false">×</button>
        <template v-if="chooser"><h2>What would you like to do?</h2><p>Create an Action against customer-authorized funding.</p><button v-for="t in ACTION_TYPES.filter(t=> t==='Funding Modification' ? permitted('funding') : t==='Credit / Adjustment' ? permitted('adjust') : t==='Create Customer Invoice' ? permitted('invoice') : true)" :key="t" class="mf-choice" @click="selectType(t)"><FileText :size="21"/><span><b>{{ t==='Direct Expense / Pass-Through' ? 'Record Direct Expense' : t }}</b><small>{{ t==='Purchase Material' ? 'Solicit vendors, create a customer quote, issue POs, and track material.' : t==='Direct Expense / Pass-Through' ? 'Record a vendor invoice or customer-directed expense.' : t==='Create Customer Invoice' ? 'Generate customer billing against one or more Actions.' : t==='Credit / Adjustment' ? 'Record a financial correction or credit.' : 'Increase or decrease authorized project funding.' }}</small></span></button></template>

        <form v-else-if="newType" class="mf-form" @submit.prevent="createAction"><h2>{{ newType }}</h2><label>Description<input v-model="form.description" required maxlength="500"/></label><div class="mf-two"><label>Request Date<input v-model="form.requestDate" type="date" required/></label><label>Customer / Requestor<input v-model="form.requestor"/></label><label>Assigned Owner<select v-model="form.ownerId"><option :value="workspace?.actor.id">{{ workspace?.actor.name }}</option><option v-for="u in users" :key="u.id" :value="u.id">{{ u.name }}</option></select></label><label>Vendor<input v-model="form.vendor" list="mf-vendors"/></label></div><div v-if="!['Funding Modification','Credit / Adjustment'].includes(newType)" class="mf-two"><label>Action Authorized Amount<input v-model.number="form.authorizedAmount" type="number" min="0" step=".01" required/></label><label>Estimated Cost<input v-model.number="form.estimatedCost" type="number" min="0" step=".01" required/></label><label>Customer Bill Amount<input v-model.number="form.billAmount" type="number" min="0" step=".01" required/></label></div><label>Notes<textarea v-model="form.notes"/></label><button class="primary-action" :disabled="busy">Create Action</button></form>

        <form v-else-if="invoiceComposer" class="mf-form" @submit.prevent="draftInvoice"><h2>Create Customer Invoice</h2><p>Select the amount to bill for each Action. Only approved Actions marked Ready to Bill are available.</p><button v-if="permitted('create')" class="secondary-action" type="button" @click="openNew('Create Customer Invoice')">Create standalone billing Action</button><div class="mf-two"><label>Invoice Date<input v-model="draft.invoiceDate" type="date" required/></label><label>Due Date<input v-model="draft.dueDate" type="date" required/></label></div><label v-for="a in billableActions" :key="a.id">{{ a.number }} · {{ a.description }}<small>Available to bill: {{ money(actionFinancials(state!,a.id).billable) }}</small><input v-model.number="draft.amounts[a.id]" type="number" min="0" step=".01" :max="actionFinancials(state!,a.id).billable/100" placeholder="0.00"/></label><p v-if="!billableActions.length">No Actions are ready. Create or approve an Action and mark it Ready to Bill.</p><button class="primary-action" :disabled="busy || !billableActions.length">Save Draft Invoice</button></form>

        <form v-else class="mf-form" @submit.prevent="submitOperation"><h2>{{ {edit:'Edit Action',approve:'Approve / Change Commitment',expense:'Record Direct Expense / Incurred Cost',funding:'Funding Modification',adjust:'Credit / Adjustment',cancel:'Cancel Action',payment:'Record Customer Payment',void_draft:'Void Draft Invoice',review:'Record Reconciliation'}[operation] }}</h2>
          <template v-if="operation==='edit'"><label>Description<input v-model="form.description" required/></label><label>Request Date<input v-model="form.requestDate" type="date" required/></label><label>Customer / Requestor<input v-model="form.requestor"/></label><label>Owner<select v-model="form.ownerId"><option :value="action?.ownerId">{{ action?.ownerName }}</option><option v-for="u in users" :key="u.id" :value="u.id">{{ u.name }}</option></select></label><label>Vendor<input v-model="form.vendor" list="mf-vendors"/></label><div class="mf-two"><label>Authorized Amount<input v-model.number="form.authorizedAmount" type="number" min="0" step=".01"/></label><label>Estimated Cost<input v-model.number="form.estimatedCost" type="number" min="0" step=".01"/></label><label>Customer Bill Amount<input v-model.number="form.billAmount" type="number" min="0" step=".01"/></label></div><label>Notes<textarea v-model="form.notes"/></label></template>
          <template v-if="operation==='approve'"><p>Available project funding: {{ money(totals.available) }}. Commit the total amount reserved for this Action.</p><label>Total Action Commitment<input v-model.number="form.commitment" type="number" min="0" step=".01" required/></label></template>
          <template v-if="operation==='expense'"><p v-if="action?.status==='Complete'" class="mf-help">Record the vendor cost without reopening this Action. Its status will remain Complete.</p><label>Vendor<input v-model="form.vendor" list="mf-vendors" required/></label><label>Vendor Invoice Number<input v-model="form.vendorInvoiceNumber" required/></label><label>Description<input v-model="form.description" required/></label><label>Expense Date<input v-model="form.expenseDate" type="date" required/></label><div class="mf-two"><label>Actual Cost<input v-model.number="form.actualCost" type="number" min=".01" step=".01" required/></label><label>Customer Bill Amount for this expense<input v-model.number="form.billAmount" type="number" min="0" step=".01" required/></label></div><label>Supporting document<select v-model="form.documentId"><option value="">No document selected</option><option v-for="d in documents" :key="d.id" :value="d.id">{{ d.name }}</option></select></label><p class="mf-help">Upload the invoice in the Documents tab. This cost posting does not issue customer billing or increase the Action bill amount.</p><label>Notes<textarea v-model="form.notes"/></label></template>
          <template v-if="operation==='adjust'"><label>Adjustment Type<select v-model="form.kind"><option>Customer Credit</option><option>Vendor Credit</option><option>Cost Adjustment</option><option>Commitment Adjustment</option><option>Payment Reversal</option></select></label><label>Affected Action<select v-model="form.targetActionId" required><option value="">Select Action</option><option v-for="a in state?.actions.filter(a=>!['Funding Modification','Credit / Adjustment'].includes(a.type))" :key="a.id" :value="a.id">{{ a.number }} · {{ a.description }}</option></select></label><label v-if="['Customer Credit','Payment Reversal'].includes(form.kind)">Affected Invoice<select v-model="form.invoiceId" required><option value="">Select Invoice</option><option v-for="i in state?.invoices.filter(i=>i.status==='Issued' && i.allocations.some(a=>a.actionId===form.targetActionId))" :key="i.id" :value="i.id">{{ i.number }}</option></select></label></template>
          <template v-if="['funding','adjust','payment'].includes(operation)"><label>{{ operation==='payment' ? 'Payment Amount' : 'Signed Change (negative for a decrease or credit)' }}<input v-model.number="form.amount" type="number" step=".01" required/></label><label>Reference / Document Number<input v-model="form.reference" required/></label></template>
          <label v-if="operation!=='expense'">{{ operation==='review' ? 'Reconciliation explanation and supporting references' : 'Reason / Explanation' }}<textarea v-model="form.reason" required/></label>
          <label v-if="permitted('override') && ['approve','funding','adjust'].includes(operation)">Funding Override Explanation (if required)<textarea v-model="form.overrideReason" placeholder="Required only when this posting would exceed funding"/></label>
          <button class="primary-action" :disabled="busy">{{ busy ? 'Saving…' : 'Save to Ledger' }}</button>
        </form>
        <div v-if="error" class="mf-alert" role="alert"><b>{{ error }}</b><p v-if="fundingError">Authorized {{ money(fundingError.authorizedFunding) }} · Current Commitments {{ money(fundingError.currentCommitments) }} · Proposed {{ money(fundingError.proposedCommitment) }} · Projected Remaining {{ money(fundingError.projectedRemainingBalance) }}</p></div>
      </section>
    </div>
    <datalist id="mf-vendors"><option v-for="v in vendors" :key="v" :value="v"/></datalist>
  </main>
</template>

<style scoped>
