ers{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin:24px 0}.mf-filters .mf-search{grid-column:span 2}.mf-page label{display:flex;flex-direction:column;gap:7px;font-size:12px;font-weight:650;color:#4b6078}.mf-page input,.mf-page select,.mf-page textarea{min-width:0;width:100%;padding:10px 11px;border:1px solid #cbd7e4;border-radius:7px;background:#fff;color:#203951;font:inherit;font-size:14px;box-sizing:border-box}.mf-page textarea{min-height:80px;resize:vertical}.mf-table{overflow:auto;margin-top:18px}.mf-table table{width:100%;border-collapse:collapse;font-size:12px}.mf-table th{text-align:left;white-space:nowrap;padding:12px;background:#f1f5fa;font-weight:700;color:#52667d}.mf-table td{padding:14px 12px;border-bottom:1px solid #e6ecf2;vertical-align:top;min-width:110px}.mf-table td:nth-child(n+5){font-variant-numeric:tabular-nums;white-space:nowrap}.mf-table a{color:#1c5c91;font-weight:750}.mf-table strong{display:block;min-width:190px}.mf-page small{display:block;line-height:1.5;font-weight:400;color:#6b7c90;margin-top:4px}.mf-pill{display:inline-block;border-radius:5px;padding:4px 7px;background:#eaf1f8;color:#355b80;white-space:nowrap}.mf-empty{text-align:center;padding:42px!important;color:#7c8a9a}.mf-alert{background:#fff1ed;border:1px solid #edc5b9;color:#943c27;padding:15px 18px;border-radius:8px;margin-bottom:18px;font-size:14px}.mf-alert p{line-height:1.7;margin:7px 0 0}.mf-notice{padding:12px 16px;border-radius:7px;background:#e9f6ee;color:#256b48}.mf-statuses{display:flex;gap:50px;margin:28px 0}.mf-statuses small{margin:0 0 7px}.mf-action-cards{margin-bottom:25px}.mf-action-cards article{padding:14px}.mf-action-cards strong{font-size:23px}.mf-record{padding:18px 0;border-bottom:1px solid #e5ecf3;font-size:14px}.mf-record p{max-width:850px;line-height:1.5}.mf-invoice{border:1px solid #dce5ed;border-radius:9px;padding:18px;margin:20px 0}.mf-invoice h3{margin:0 0 5px}.mf-allocation{display:flex;justify-content:space-between;gap:2